  // PC-56 TENANT-4b · W145/W146 — the organisation's payout queue and the batch approval gate.
  'po.title': 'Payout',
  'po.intro': 'Aapke sadasyon aur shramikon ko paisa. Order poore hone aur cycle band hone par payout apne aap qatar mein aate hain; ve ek aise batch mein jaate hain jise doosre vyakti ne hastakshar kiya ho.',
  'po.makerCheckerNote': 'Ek vyakti aaj raat ka batch taiyaar karta hai, doosra use manzoor karta hai. Is wave se pehle woh hastakshar kahin nahin tha — ek scheduled job apne aap paisa bhej deta tha.',
