  // PC-56 TENANT-4c · W147/W148 — the settlement cycle and the statements it produces.
  'stl.title': 'Settlement',
  'stl.intro': 'Prati-vikreta settlement cycle: kul bikri − commission − tax = shudh bhugtan. Cycle band karna ek avadhi ke vyapaar ko aise statement mein badalta hai jo aapke sadasya haath mein rakh sakein, aur ismein do log lagte hain.',
  'stl.restricted': 'Settlement cycle ke liye settlement.close anumati chahiye. Admin se maangein — cycle par koi asar nahin.',
  'stl.loadError': 'Cycle load nahin ho paya. Avadhi mein kuch nahin badla. Phir koshish karein.',
  'stl.noCycle': 'Abhi koi cycle khula nahin. Jaise hi pehli bikri iski avadhi mein nipatti hai, cycle khul jaata hai.',
  'stl.currentCycle': 'Vartamaan cycle',
  'stl.cycleGrossHint': '{sellers} vikreta jinki bikri abhi nahin nipti · {period}',
  'stl.status.open': 'khula',
  'stl.status.pending_close': 'doosre vyakti ka intezaar',
  'stl.status.closing': 'band ho raha — statement ban rahe hain',
  'stl.status.closed': 'band',
  'stl.status.rejected': 'band karna asweekrit',
  'stl.status.unknown': 'agyaat sthiti',
  'stl.progressTitle': 'Statement',
  'stl.progress.notStarted': 'Abhi koi statement nahin. Doosre vyakti ki manzoori ke baad banna shuru hote hain.',
  'stl.progress.generating': '{expected} mein se {generated} bane · {remaining} bache',
  'stl.progress.complete': 'Sabhi {generated} statement ban gaye.',
  'stl.progress.overGenerated': '{expected} apekshit the par {generated} statement hain. Manzoori ke baad kisi vikreta ki bikri jud gayi — dekhna theek rahega ki kiski.',
  'stl.progressHint': 'Har statement apna alag transaction hai, isliye beech mein vifalta ek vikreta ki dobara koshish hai, poori avadhi ki nahin. Isi wajah se yahan ginti dikhti hai, "sab ek saath" ka daava nahin: ek lakh vikreta ka ek hi transaction kisi bhi database se maangna theek nahin.',
  'stl.signatures': 'Hastakshar',
  'stl.notRequested': 'Is cycle ke liye band karne ki koi maang nahin hui.',
  'stl.requestedAt': 'Band karne ki maang {at}',
  'stl.decidedAt': 'Nirnay {at}',
  'stl.twoHumans': 'Cycle band karne mein sada do log lagte hain: ek maangta hai, doosra manzoori deta hai. Koi aisi raashi nahin jiske neeche ek vyakti kaafi ho — cycle kisi ki rozi ki avadhi hai, mahaz aankda nahin.',
  'stl.closeTitle': 'Yeh cycle band karein',
  'stl.requestConfirm': 'Is cycle ko band karne ki maang: {sellers} vikreta, {gross} kul bikri. Uske baad doosra admin manzoori deta hai, phir statement bante hain.',
  'stl.requestClose': 'Band karne ki maang',
  'stl.closeBlocked.noPermission': 'Cycle band karne ke liye settlement.close anumati chahiye.',
  'stl.closeBlocked.notOpen': 'Yeh cycle khula nahin — ya band ho raha hai ya ho chuka hai.',
  'stl.closeBlocked.periodNotEnded': 'Is cycle ka aakhri din abhi poora nahin hua. Jaldi band karne se aaj ki bikri us avadhi se bahar ho jaayegi jiski wah hai, aur vikreta ko pata bhi nahin chalega ki kis statement mein gayi.',
  'stl.closeBlocked.nothingToSettle': 'Is avadhi mein koi bakaya bikri nahin hai, isliye band karne ko kuch nahin.',
  'stl.youRequested': 'Aapne yeh maang ki thi, isliye aap hi manzoori nahin de sakte. Doosre admin se hastakshar karayein — apni maang aap asweekar kar sakte hain.',
  'stl.approveConfirm': '{sellers} vikreta ke liye band karne ki manzoori dein. Uske baad prati vikreta ek statement banta hai.',
  'stl.approveClose': 'Band karne ki manzoori',
  'stl.noteOptional': 'Tippani (vaikalpik)',
  'stl.rejectNote': 'Yeh band karna kyon asweekar kar rahe hain? Maang karne wale ko bataya jaayega.',
  'stl.rejectNoteHint': 'Kam se kam {floor} akshar. Cycle phir khul jaata hai aur kaaran theek hone par dobara maanga ja sakta hai.',
  'stl.rejectClose': 'Kaaran ke saath asweekar karein',
  'stl.generate': 'Statement banayein',
  'stl.generateHint': 'Is cycle ke agle statement banayein. Jab tak bache dikhein, dobara dabayein — kaam wahin se aage badhta hai, shuru se nahin, isliye bada tenant kai chakron mein poora hota hai, ek vishaal transaction mein nahin.',
  'stl.sellersTitle': 'Is cycle ke vikreta',
