  'dairy.centres.gap.transfer': "यहाँ से सदस्यता एक केंद्र से दूसरे केंद्र नहीं भेजी जा सकती। भेजना आसान है; इतिहास को सच्चा रखना नहीं — बंद हो चुके पखवाड़े का रजिस्टर बिल का केंद्र आज के मार्ग से पढ़ता है, इसलिए पहला ही हस्तांतरण हर पुराने चक्र का श्रेय बदल देता। यह सुविधा उस पाठ के सुधार के साथ आएगी।",
