  'dairy.centres.gap.reliefOperator': "एक समय में केंद्र की ज़िम्मेदारी एक ही व्यक्ति की होती है। जो सहकारी दो पारियों में दो ऑपरेटर वास्तव में रखती है, उसका मॉडल नहीं बना है, और यहाँ दूसरा नाम ऐसा खाना होगा जिसमें कुछ लिखा ही नहीं जाता।",

