  'templates.provider.dlt': 'SMS के शब्द भेजने से पहले DLT में पंजीकृत होने चाहिए। आपके जाँचकर्ता की मंज़ूरी इस संस्करण को प्रदाता के पास भेजती है (स्थिति "प्रदाता के पास") और यह यहाँ से कभी चालू नहीं होता; DLT पंजीकरण प्लेटफ़ॉर्म डेस्क का काम है, और तब तक पिछले शब्द भेजे जाते रहते हैं।',
