  'templates.actDone.retire': 'हटा दिया। अगली बार से आपके सदस्यों को प्लेटफ़ॉर्म डिफ़ॉल्ट मिलेगा — या, जहाँ वह नहीं है, वह चैनल "कोई टेम्पलेट नहीं" दर्ज करेगा।',
  'templates.refused.sendTest': '"मेरे फ़ोन पर टेस्ट भेजें" नहीं बना है: टेनेंट के पास परखने के लिए कोई असली भेजने का रास्ता नहीं है (नोटिफ़ायर यहाँ जुड़ा नहीं है), और DLT में पंजीकृत न हुए शब्दों पर टेस्ट SMS ऑपरेटर पर रुक जाएगा। नीचे का पूर्वावलोकन प्लेटफ़ॉर्म का अपना रेंडर है।',
  'templates.refused.experiment': '"नया प्रयोग" नहीं बना है: कोई प्रयोग तालिका नहीं है (DELTA-029) — दर्ज करने के लिए कोई वेरिएंट बँटवारा, एक्सपोज़र गिनती या विजेता नहीं है।',
  'templates.refused.dltReverify': '"बदलाव अगली बार से पहले DLT दोबारा जाँचते हैं" प्लेटफ़ॉर्म डेस्क का काम है: टेनेंट DLT को जमा नहीं कर सकता। यहाँ सच यह है: SMS बदलाव इस कंसोल से कभी चालू नहीं होता, इसलिए पिछले शब्द भेजे जाते रहते हैं।',
  'templates.refused.deliveryStats': 'यहाँ मापा नहीं जाता: हर टेम्पलेट संस्करण की डिलीवरी दर्ज नहीं होती, और आपकी संस्था का डिलीवरी लॉग अलग पेज है (अभी बना नहीं)।',
  'templates.refused.draftHistoryCanon': 'ड्राफ़्ट ही संस्करण हैं: हर एक रखा जाता है, किसने लिखा और किसने तय किया उसके साथ।',
  'templates.refused.compiledCache': 'कोई "कम्पाइल्ड कैश" नहीं है: भेजना मंज़ूर संस्करण सीधे डेटाबेस से पढ़ता है, इसलिए पेज लोड न होने से भेजे जाने वाले शब्दों पर कोई असर नहीं।',
  'templates.refused.retryPageLoad': '"फिर कोशिश" पेज दोबारा खोलना है, कोई कार्य नहीं: आपकी ओर से कुछ दोबारा नहीं किया जाता।',
