  'auditor.refused.platformSignature': "हस्ताक्षर नहीं: प्लेटफ़ॉर्म हस्ताक्षर कुंजी नहीं है, इसलिए किसी एक्सपोर्ट या पैक पर हस्ताक्षर या \"सत्यापन योग्य\" चिह्न नहीं (संस्थापक की कुंजी, अभी जारी नहीं)।",
  'auditor.refused.sharedChain': "\"शुरू से अंत तक हैश शृंखला अखंड\" का दावा नहीं: प्लेटफ़ॉर्म खाते हर सहकारी साझा करती है और धारियों में बँटे हैं, इसलिए एक सहकारी से उनकी शृंखला नहीं जाँची जा सकती।",
