  'auditor.refused.reversalsLinked': "\"सभी उलटाव जुड़े\" नहीं दिखाया: खाता-बही उलटाव से मूल लेन-देन की कोई कड़ी दर्ज नहीं करती।",
  'auditor.refused.numberingGaps': "\"क्रमांक में कोई अंतर नहीं\" का दावा नहीं: प्रविष्टि संख्या डेटाबेस क्रम हैं, जिनमें स्वभावतः अंतर होते हैं।",
  'auditor.refused.exceptionRegister': "इस प्लेटफ़ॉर्म पर कोई अपवाद रजिस्टर नहीं, इसलिए \"खुले अपवाद\" यहाँ संख्या नहीं।",
  'auditor.refused.accessWindow': "इस प्लेटफ़ॉर्म पर ऑडिटर पहुँच की अभी कोई समाप्ति, दर्ज नियुक्ति-पत्र या बदलाव सूचना नहीं — रद्द करना भूमिका हटाना है।",
  'auditor.refused.firmIdentity': "कोई नियुक्ति रिकॉर्ड ऑडिट फ़र्म का नाम नहीं रखता, इसलिए कोई नहीं दिखाया।",
