  'auditor.refused.gstPayableTie': "gst_payable प्लेटफ़ॉर्म खाते से नहीं जोड़ा: वह खाता हर सहकारी साझा करती है; दिखाया गया मिलान इस सहकारी के अपने चालान योग हैं।",
  'auditor.refused.ekycBlocked': "\"ई-KYC से रुके\" आवेदन नहीं गिने: योजना आवेदन से ई-KYC निर्णय की कोई कड़ी नहीं।",
  'auditor.refused.signAttest': "\"हस्ताक्षर और प्रमाणित करें\" उपलब्ध नहीं: कोई प्रमाणन रिकॉर्ड और हस्ताक्षर कुंजी नहीं। पैक बिना हस्ताक्षर रहता है।",
