  'res.how.title': "ऐप मतदान कैसे होता है",
  'res.how.1': "सूचना: मतदान खुलते ही हर सदस्य को ऐप में और पुश सूचना से, उसकी अपनी भाषा (अंग्रेज़ी, हिंदी, गुजराती) में बताया जाता है।",
  'res.how.2': "मतपत्र: एक टैप; मतदान बंद होने तक मत बदला जा सकता है, उसके बाद अंतिम।",
  'res.how.3': "हर मत प्रस्ताव द्वारा घोषित विकल्प है (पक्ष · विरोध · तटस्थ), हर सदस्य का एक — शेयर पूँजी जोड़ते हैं, कभी अतिरिक्त मत नहीं।",
  'res.passes.title': "यदि पारित हो",
  'res.passes.body': "लाभांश या संरक्षण बोनस सामान्य धन मार्ग से चलता है: प्रस्ताव का सूत्र → हर सदस्य की राशि → एक व्यक्ति द्वारा तैयार और दूसरे द्वारा पुष्ट भुगतान रन → भुगतान डेस्क की दो-व्यक्ति बैच स्वीकृति। केवल वही प्रस्ताव भुगतान कर सकता है जिसका दर्ज परिणाम \"पारित\" है; असफल मत नहीं।",
  'res.footer': "प्रस्ताव का जीवन-चक्र दर्ज (किसने खोला, किसने बंद किया, कब, क्यों) · बंद होने के बाद मत अपरिवर्तनीय · परिणाम हर सदस्य को ऐप में प्रकाशित।",
  'res.state.flaggedOff.title': "प्रस्ताव और मतदान बंद है",
  'res.state.flaggedOff.body': "यह मॉड्यूल इस सहकारी के लिए बंद है (फ़ीचर फ़्लैग)। कुछ टूटा नहीं — यह चालू नहीं है। योजना सेटिंग देखें।",
  'res.state.restricted.title': "मसौदा बनाना सीमित है",
  'res.state.restricted.body': "मसौदा बनाना, मतदान खोलना और बंद करना शासन अनुमति माँगते हैं। मत स्वयं हर पात्र सदस्य का है — यह कंसोल कभी किसी के लिए मत नहीं डालता।",
  'res.state.notFound.title': "प्रस्ताव नहीं मिला",
  'res.state.notFound.body': "इस सहकारी का कोई प्रस्ताव इस आईडी का नहीं है।",
  'res.state.error.title': "प्रस्ताव लोड नहीं हो सके",
  'res.state.error.body': "प्रस्ताव अभी पढ़े नहीं जा सके। कुछ नहीं बदला; डाले गए मत सुरक्षित हैं।",
  'res.refused.smsVoice': "नहीं भेजा जाता: बिना स्मार्टफ़ोन वाले सदस्यों के लिए SMS और वॉयस कॉल — इस प्लेटफ़ॉर्म पर कोई स्वीकृत SMS टेम्पलेट और कोई वॉयस प्रदाता नहीं है।",
  'res.refused.noticePeriod': "लागू नहीं: \"बंद होने से 14 दिन पहले, उपनियम न्यूनतम\" — सूचना कब भेजी गई यह दर्ज नहीं होता, इसलिए सूचना अवधि मापी नहीं जा सकती।",
  'res.refused.voiceReadout': "नहीं बना: मतपत्र को आवाज़ में पढ़ना — कोई वॉयस प्रदाता नहीं।",
  'res.refused.paperBallot': "नहीं बना: MCC काउंटर पर कागज़ी विकल्प — कागज़ी मत में यह दर्ज होना चाहिए कि किसने किसकी ओर से डाला, और वह रिकॉर्ड अभी नहीं है।",
  'res.refused.board': "इस प्लेटफ़ॉर्म पर कोई बोर्ड भूमिका नहीं है: मसौदा और मतदान खोलना या बंद करना शासन अनुमति है (टेनेंट एडमिन के पास)।",
  'res.refused.boardElection': "बोर्ड चुनाव में उम्मीदवारों के नाम होते हैं, और इस प्लेटफ़ॉर्म पर कोई उम्मीदवार सूची नहीं है — यहाँ इसका मसौदा या मतदान नहीं हो सकता।",
  'res.refused.perLanguageText': "हर प्रस्ताव का एक पाठ: सदस्यों को जैसा लिखा है वैसा ही दिखता है — प्रस्ताव के अपने शब्दों का भाषा-वार संस्करण नहीं है।",
  'res.refused.autoClose': "बंद होने के समय के बाद मत अपने आप अस्वीकार होते हैं, पर प्रस्ताव एक व्यक्ति बंद करता है — बंद करना परिणाम दर्ज करता है, और परिणाम किसी का दर्ज कार्य है।",
