  'swb.run.act.pay': "फिर से भुगतान",
  'swb.run.act.refuse': "रन अस्वीकार करें",
  'swb.run.rule.prepare': "इस सप्ताह का रन अभी तैयार करता है: हर सक्रिय एम्बेसडर की अब तक की बकाया कमाई, और पूरे महीने सक्रिय रहे लोगों का वजीफ़ा। कुछ नहीं हिलता; फ़ंडिंग मुख्य वॉलेट से पढ़ी जाती है।",
  'swb.run.rule.confirm': "पुष्टि करना रन का अभी भुगतान करता है: मुख्य वॉलेट से हर एम्बेसडर को एक ट्रांसफ़र। जो पंक्ति वॉलेट कवर नहीं कर सकता वह कमी सहित बिना फ़ंड चिह्नित होती है — उसके लिए कुछ नहीं हिलता। आप तैयार करने वाले व्यक्ति नहीं होने चाहिए।",
  'swb.run.rule.pay': "केवल अब भी बकाया पंक्तियों (बिना फ़ंड या विफल) का मुख्य वॉलेट की मौजूदा स्थिति से भुगतान करता है। चुकाई गई पंक्तियाँ कभी दो बार नहीं चुकाई जातीं।",
  'swb.run.rule.refuse': "अस्वीकार करना बिना कुछ चुकाए रन बंद करता है। कमाई बकाया रहती है और अगला रन उसे उठाता है।",
  'swb.run.notOffered.prepare': "एक रन पहले से खुला है — पहले उसकी पुष्टि, भुगतान या अस्वीकार करें।",
  'swb.run.notOffered.confirm': "यह रन अभी आपके द्वारा पुष्ट नहीं हो सकता: यह तैयार नहीं है, या आपने इसे तैयार किया।",
  'swb.run.notOffered.pay': "केवल आंशिक या बिना फ़ंड वाला रन फिर से चुकाया जाता है — और कभी तैयार करने वाले द्वारा नहीं।",
  'swb.run.notOffered.refuse': "केवल तैयार रन अस्वीकार किया जा सकता है।",
  'swb.run.done.prepare': "{n} एम्बेसडर के साथ रन तैयार। कोई दूसरा टेनेंट एडमिन इसकी पुष्टि करेगा।",
  'swb.run.done.confirm': "रन पुष्ट: {paid} चुकाए ({amount}), {unfunded} बिना फ़ंड, {failed} विफल।",
  'swb.run.done.pay': "फिर से भुगतान: {paid} चुकाए ({amount}), {unfunded} अब भी बिना फ़ंड, {failed} विफल।",
  'swb.run.done.refuse': "रन अस्वीकृत। कुछ नहीं हिला; कमाई बकाया रहती है।",
  'swb.run.refused.dairyCycle': "\"डेयरी चक्र के साथ भुगतान\" नहीं बना: रन का अपना साप्ताहिक चक्र है, दूध भुगतान से कोई जुड़ाव नहीं।",
  'swb.run.refused.proRata': "वजीफ़ा केवल पूरे महीनों का चुकाया जाता है: महीने के बीच नामांकित या निलंबित एम्बेसडर को उस महीने का नहीं मिलता (अनुपातिक नहीं बना)।",
  'swb.run.refused.retry': "पुनः प्रयास यह पेज फिर से लोड करता है; कुछ नहीं बदलता।",
  'swb.att.title': "हाज़िरी समीक्षा",
