  'swb.att.lede': "खेत से {m} मी से अधिक दूर की क्लॉक-इन दर्ज होती है और समीक्षा के लिए चिह्नित होती है, कभी मना नहीं होती। दिन की पुष्टि तक कोई मज़दूरी नहीं बनती।",
  'swb.att.law': "डेटाबेस द्वारा लागू: कोई मज़दूर अपने दिन की पुष्टि या ज़मानत कभी नहीं कर सकता; समीक्षा के लिए चिह्नित दिन ज़मानत के बिना कभी पुष्ट नहीं होता; जिसने काग़ज़ी दिन दर्ज किया वह उसकी ज़मानत नहीं दे सकता।",
