  'swb.att.act.confirm_clean': "सभी साफ़ रिकॉर्ड पुष्ट करें",
  'swb.att.act.backfill': "काग़ज़ी प्रविष्टि",
  'swb.att.rule.vouch': "आप ज़मानत देते हैं कि यह दिन दर्ज अनुसार काम हुआ, भले क्लॉक-इन सीमा के बाहर (या काग़ज़ पर) था। जो देखा वह लिखें — 10 से 500 अक्षर। फिर दिन पुष्ट हो सकता है।",
  'swb.att.rule.refuse': "अस्वीकार का अर्थ है यह दिन कभी नहीं चुकाया जाएगा। कारण लिखें — 10 से 500 अक्षर।",
  'swb.att.rule.confirm': "पुष्टि से 18:00 IST मज़दूरी रन इस दिन का भुगतान काम के एस्क्रो से कर सकता है। मज़दूर अपने दिन की पुष्टि कभी नहीं कर सकता।",
  'swb.att.rule.confirm_clean': "उन कामों के हर साफ़ दिन (सीमा के भीतर स्वयं क्लॉक-इन, क्लॉक-आउट हुआ) की पुष्टि करता है जिनकी आप पुष्टि कर सकते हैं — हर दिन अलग से, अपनी ऑडिट प्रविष्टि के साथ। आपके अपने दिन छोड़ दिए जाते हैं।",
  'swb.att.rule.backfill': "हस्ताक्षरित काग़ज़ी शीट से एक दिन दर्ज करता है। यह \"समीक्षा चाहिए\" के रूप में बनता है: कोई दूसरा व्यक्ति (नियोक्ता या समीक्षक) ज़मानत देकर पुष्टि करता है। 10–500 अक्षरों का कारण ज़रूरी है।",
  'swb.att.done.vouch': "ज़मानत दी गई। अब दिन पुष्ट हो सकता है।",
  'swb.att.done.refuse': "अस्वीकृत। यह दिन नहीं चुकाया जाएगा।",
  'swb.att.done.confirm': "पुष्ट। 18:00 IST मज़दूरी रन इसका भुगतान करेगा।",
  'swb.att.done.confirm_clean': "{considered} में से {n} साफ़ दिन पुष्ट; आपके अपने {skipped} छोड़े गए।",
  'swb.att.done.backfill': "काग़ज़ी दिन दर्ज — इसे किसी और की ज़मानत और पुष्टि चाहिए।",
  'swb.att.refused.offlineStore': "ऑफ़लाइन ऑन-डिवाइस क्लॉक स्टोर नहीं बना (मोबाइल): आज क्लॉक-इन के लिए कनेक्शन चाहिए।",
  'swb.att.refused.retry': "पुनः प्रयास यह पेज फिर से लोड करता है; कुछ नहीं बदलता।",
  'swb.wage.title': "मज़दूरी रन",
  'swb.wage.lede': "हर दिन 18:00 IST पर रन हर पुष्ट, बकाया दिन का भुगतान हर काम के एस्क्रो से करता है (होल्ड → मज़दूर वॉलेट)। विफल पंक्ति अगले दिन 16:00 IST पर फिर कोशिश करती है, तीन दिन तक दिन में एक बार, फिर विफल कहलाती है।",
  'swb.wage.tile.today': "आज का रन",
