  'swd.code.unknown': "कार्य ऐसे कारण से विफल हुआ जिसे कंसोल नहीं पहचानता।",
  'swd.agm.method.gmv': "GMV = वित्त वर्ष में पूरे हुए हर ऑर्डर का माल मूल्य (ऑर्डर उप-योग, डिलीवरी, शुल्क और कर से पहले)। पूरा होने के बाद रिफ़ंड या रद्द हुए ऑर्डर नहीं गिने जाते। स्रोत: ऑर्डर।",
  'swd.agm.method.paid_to_members': "सदस्यों को भुगतान = वर्ष में escrow_release के तहत सदस्यों के मुख्य वॉलेट में दर्ज लेजर प्रविष्टियों का शुद्ध योग: ऑर्डर निपटान जमा हैं, विवाद और वापसी की वसूली नामे हैं। स्रोत: लेजर।",
  'swd.agm.method.paid_share': "हिस्सा = सदस्यों को भुगतान ÷ GMV, दोनों दिखाए गए, एक ही मुद्रा में (बेसिस पॉइंट, नीचे की ओर पूर्णांकित)। दो तथ्यों का अनुपात।",
  'swd.agm.method.platform_fees': "प्लेटफ़ॉर्म शुल्क = वर्ष में इस समिति के ऑर्डर निपटान और वसूली से प्लेटफ़ॉर्म शुल्क खाते में दर्ज शुद्ध राशि। स्रोत: लेजर।",
  'swd.agm.method.gst_on_commission': "कमीशन पर GST = वर्ष में इस समिति के ऑर्डर निपटान से प्लेटफ़ॉर्म GST-देय खाते में दर्ज शुद्ध राशि। स्रोत: लेजर।",
  'swd.agm.method.tenant_commission': "समिति कमीशन = वर्ष में ऑर्डर निपटान से इस समिति के अपने कमीशन खाते में दर्ज शुद्ध राशि। स्रोत: लेजर।",
  'swd.agm.method.surplus': "FPO अधिशेष नहीं दिया गया: प्लेटफ़ॉर्म समिति के परिचालन खर्च का कोई लेजर नहीं रखता, इसलिए तथ्यों से अधिशेष नहीं निकाला जा सकता। लेखा-परीक्षित खाते देखें।",
  'swd.agm.method.operating_costs': "परिचालन खर्च नहीं दिया गया: प्लेटफ़ॉर्म पर कोई खर्च लेजर नहीं है। समिति की अपनी बहियाँ (और उसके लेखा परीक्षक) स्रोत हैं।",
  'swd.agm.method.statements': "वित्त वर्ष से मेल खाती अवधि के निपटान विवरण, जो सदस्यों को जारी हुए। हर सदस्य विवरण पेज पर अपना पढ़ता है।",
  'swd.agm.method.snapshot': "वर्ष के अंत पर शेयर रजिस्टर: उस समय मौजूद और उसके बाद न बदली पंक्तियाँ। कोई बदली हो तो अंश नहीं दिया जाता — रजिस्टर इतिहास नहीं रखता।",
  'swd.agm.method.closed_in_fy': "वित्त वर्ष में बंद हुए प्रस्ताव, बंद होते समय दर्ज परिणाम के साथ (उस समय दर्ज कोरम और बहुमत)।",
  'swd.agm.method.annexure': "लेखा परीक्षक की रिपोर्ट, जैसी समिति ने अपलोड की — प्लेटफ़ॉर्म द्वारा न बनाई गई, न जाँची गई।",
  'swd.agm.method.quorum': "कोरम, जैसा governance.quorum_bp सेटिंग में दर्ज है (समिति का अपना, या न होने पर प्लेटफ़ॉर्म का डिफ़ॉल्ट)।",
  'swd.agm.method.notice_period': "AGM सूचना अवधि नहीं दी गई: प्लेटफ़ॉर्म पर इसकी कोई उपनियम सेटिंग नहीं है, और याद से लिखी संख्या डेटा नहीं है।",
